// cache_stress — co-activate icache (fetch_stall) AND dcache (memory_stall) pressure
// so the status crosses fill their simultaneous-stall tuples:
//   cross_ipc_stalls  <*,fetch-stalled,mem-stalled>  (both caches stalled at once)
//   cross_ipc_stalls  <zero,*,mem-stalled>           (zero retire DURING mem backpressure)
//
// No single existing kernel does both: text_big thrashes the icache (600 resident
// functions swept by runtime index -> fetch_stall) but touches little data; mem_stress
// bursts the dcache MSHR (-> memory_stall) but has a tiny .text and keeps IPC at med.
// cache_stress reuses text_big's 600-function resident table for the icache pressure and
// INTERLEAVES a compute-free independent-load burst into the sweep, each burst followed
// immediately by a dependent reduce with NO masking compute:
//   * the independent burst fills the MSHR  -> memory_stall (dcache request backpressure)
//   * the big-text sweep between bursts misses the icache -> fetch_stall (overlaps mem)
//   * the dependent reduce right after a burst stalls the pipe until the loads return,
//     with nothing else to retire -> a zero-IPC window co-sampled with memory_stall.
// NLD=12 independent loads (proven-safe burst; >~16 spills registers and deadlocks spawn).
//
// Deterministic + printf-free (INV-1): out_buf is a pure function of (in[i], scattered
// data[]), identical on host recompute and device -> DUT-vs-SimX scoreboard-safe.

#include <vx_intrinsics.h>
#include <vx_spawn.h>

